begin; create extension if not exists citext with schema extensions;
create table if not exists profiles(id uuid primary key references auth.users on delete cascade,username extensions.citext unique not null,email extensions.citext unique not null,display_name text not null,whatsapp text,avatar_url text,role text not null check(role in('resident','observer','assessor','owner')),residency_year smallint check(residency_year between 1 and 5),is_active boolean default true,progression_status text default'in_training' check(progression_status in('in_training','eligible_for_upgrade','reassessment_required','completed')),reassessment_due date,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists chapters(id bigint generated by default as identity primary key,slug text unique not null,title text not null,description text,year_from smallint not null,year_to smallint not null,sort_order int default 0,is_active boolean default true);
create table if not exists knowledge_items(id bigint generated by default as identity primary key,chapter_id bigint references chapters on delete cascade,title text not null,description text,sort_order int default 0,is_active boolean default true,unique(chapter_id,title));
create table if not exists skills(id bigint generated by default as identity primary key,chapter_id bigint references chapters on delete cascade,title text not null,description text,expected_level smallint default 1,sort_order int default 0,is_active boolean default true,unique(chapter_id,title));
create table if not exists knowledge_progress(resident_id uuid references profiles on delete cascade,knowledge_item_id bigint references knowledge_items on delete cascade,status text default'in_progress',updated_at timestamptz default now(),primary key(resident_id,knowledge_item_id));
create table if not exists skill_levels(resident_id uuid references profiles on delete cascade,skill_id bigint references skills on delete cascade,level smallint check(level between 1 and 5),updated_at timestamptz default now(),primary key(resident_id,skill_id));
create table if not exists skill_logs(id bigint generated by default as identity primary key,resident_id uuid references profiles on delete cascade,skill_id bigint references skills on delete cascade,performed_on date not null,supervisor_name text not null,notes text,created_at timestamptz default now());
create table if not exists observer_reviews(id bigint generated by default as identity primary key,observer_id uuid references profiles,resident_id uuid references profiles on delete cascade,chapter_id bigint references chapters,category text check(category in('knowledge','skill','attitude')),observed_on date not null,place text not null,comment text not null,observer_signature text not null,created_at timestamptz default now());
create table if not exists assessor_assignments(id bigint generated by default as identity primary key,assessor_id uuid references profiles on delete cascade,resident_id uuid references profiles on delete cascade,chapter_id bigint references chapters,residency_year smallint,is_active boolean default true,created_by uuid references profiles,created_at timestamptz default now());
create table if not exists assessment_deduction_reasons(id bigint generated by default as identity primary key,domain text check(domain in('knowledge','skills','attitude')),code text unique,label text,sort_order int default 0,is_active boolean default true);
create table if not exists assessments(id uuid primary key default gen_random_uuid(),resident_id uuid references profiles,assessor_id uuid references profiles,assessor_signature text not null,chapter_id bigint references chapters,assessed_year smallint,assessment_type text check(assessment_type in('initial','reassessment')),assessment_date date default current_date,knowledge_score numeric(4,1),skills_score numeric(4,1),attitude_score numeric(4,1),total_score numeric(5,1) generated always as(knowledge_score+skills_score+attitude_score)stored,knowledge_pass boolean,skills_pass boolean,attitude_pass boolean,overall_pass boolean,knowledge_reason_ids bigint[] default'{}',skills_reason_ids bigint[] default'{}',attitude_reason_ids bigint[] default'{}',knowledge_justification text,skills_justification text,attitude_justification text,assessor_notes text,reassessment_due date,created_at timestamptz default now());
create or replace function current_role()returns text language sql stable security definer set search_path=public as $$select role from profiles where id=auth.uid() and is_active$$;
create or replace function is_owner()returns boolean language sql stable security definer set search_path=public as $$select coalesce((select role='owner' and is_active from profiles where id=auth.uid()),false)$$;
create or replace function assessor_access(r uuid,c bigint default null)returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from assessor_assignments a join profiles p on p.id=r where a.assessor_id=auth.uid() and a.is_active and(a.resident_id is null or a.resident_id=r)and(a.residency_year is null or a.residency_year=p.residency_year)and(c is null or a.chapter_id is null or a.chapter_id=c))$$;
create or replace function new_user_profile()returns trigger language plpgsql security definer set search_path=public,extensions as $$declare r text;u text;begin r:=case when lower(new.email)='drmohamedalaa90@gmail.com'then'owner'when new.raw_user_meta_data->>'role'in('resident','observer','assessor')then new.raw_user_meta_data->>'role'else'resident'end;u:=coalesce(nullif(new.raw_user_meta_data->>'username',''),split_part(new.email,'@',1));insert into profiles(id,username,email,display_name,role,residency_year)values(new.id,u,new.email,coalesce(nullif(new.raw_user_meta_data->>'display_name',''),u),r,case when r='resident'then coalesce(nullif(new.raw_user_meta_data->>'residency_year','')::smallint,1)end);return new;end$$;
drop trigger if exists auth_profile on auth.users;create trigger auth_profile after insert on auth.users for each row execute function new_user_profile();
insert into profiles(id,username,email,display_name,role,residency_year)select id,split_part(email,'@',1),email,split_part(email,'@',1),case when lower(email)='drmohamedalaa90@gmail.com'then'owner'else'resident'end,case when lower(email)<>'drmohamedalaa90@gmail.com'then 1 end from auth.users on conflict do nothing;
create or replace function protect_profile()returns trigger language plpgsql security definer set search_path=public as $$begin if auth.uid()is not null and not is_owner()then new.username:=old.username;new.email:=old.email;new.role:=old.role;new.residency_year:=old.residency_year;new.is_active:=old.is_active;new.progression_status:=old.progression_status;new.reassessment_due:=old.reassessment_due;end if;new.updated_at:=now();return new;end$$;
drop trigger if exists protect_profile_t on profiles;create trigger protect_profile_t before update on profiles for each row execute function protect_profile();
create or replace function search_residents(search_text text default null,filter_year smallint default null)returns table(id uuid,display_name text,username text,residency_year smallint,avatar_url text)language plpgsql stable security definer set search_path=public as $$begin if current_role()not in('observer','assessor','owner')then raise exception'Not authorised';end if;return query select p.id,p.display_name,p.username::text,p.residency_year,p.avatar_url from profiles p where p.role='resident'and p.is_active and(filter_year is null or p.residency_year=filter_year)and(search_text is null or p.display_name ilike'%'||search_text||'%'or p.username::text ilike'%'||search_text||'%')and(current_role()<>'assessor'or assessor_access(p.id,null))order by p.display_name limit 50;end$$;
create or replace function get_my_observer_reviews()returns table(id bigint,resident_name text,category text,observed_on date,place text,comment text,observer_signature text)language sql stable security definer set search_path=public as $$select r.id,p.display_name,r.category,r.observed_on,r.place,r.comment,r.observer_signature from observer_reviews r join profiles p on p.id=r.resident_id where r.observer_id=auth.uid()order by r.observed_on desc$$;
create or replace function submit_assessment(p_resident_id uuid,p_chapter_id bigint,p_assessment_type text,p_knowledge_score numeric,p_skills_score numeric,p_attitude_score numeric,p_knowledge_reason_ids bigint[]default'{}',p_skills_reason_ids bigint[]default'{}',p_attitude_reason_ids bigint[]default'{}',p_knowledge_justification text default null,p_skills_justification text default null,p_attitude_justification text default null,p_assessor_notes text default null)returns jsonb language plpgsql security definer set search_path=public as $$declare y smallint;t numeric;ok boolean;due date;sig text;i uuid;begin if current_role()<>'assessor'or not assessor_access(p_resident_id,p_chapter_id)then raise exception'Not assigned';end if;if p_knowledge_score<10 and nullif(trim(p_knowledge_justification),'')is null or p_skills_score<10 and nullif(trim(p_skills_justification),'')is null or p_attitude_score<10 and nullif(trim(p_attitude_justification),'')is null then raise exception'Deductions require justification';end if;select residency_year into y from profiles where id=p_resident_id;select display_name into sig from profiles where id=auth.uid();t:=p_knowledge_score+p_skills_score+p_attitude_score;ok:=p_knowledge_score>=6 and p_skills_score>=7 and p_attitude_score>=8 and t>=21;due:=case when ok then null else(current_date+interval'2 months')::date end;insert into assessments(resident_id,assessor_id,assessor_signature,chapter_id,assessed_year,assessment_type,knowledge_score,skills_score,attitude_score,knowledge_pass,skills_pass,attitude_pass,overall_pass,knowledge_reason_ids,skills_reason_ids,attitude_reason_ids,knowledge_justification,skills_justification,attitude_justification,assessor_notes,reassessment_due)values(p_resident_id,auth.uid(),sig,p_chapter_id,y,p_assessment_type,p_knowledge_score,p_skills_score,p_attitude_score,p_knowledge_score>=6,p_skills_score>=7,p_attitude_score>=8,ok,p_knowledge_reason_ids,p_skills_reason_ids,p_attitude_reason_ids,p_knowledge_justification,p_skills_justification,p_attitude_justification,p_assessor_notes,due)returning id into i;update profiles set progression_status=case when ok then'eligible_for_upgrade'else'reassessment_required'end,reassessment_due=due where id=p_resident_id;return jsonb_build_object('id',i,'overall_pass',ok);end$$;
create or replace function owner_upgrade_resident(p_resident_id uuid)returns void language plpgsql security definer set search_path=public as $$begin if not is_owner()then raise exception'Owner only';end if;update profiles set residency_year=least(residency_year+1,5),progression_status=case when residency_year>=5 then'completed'else'in_training'end,reassessment_due=null where id=p_resident_id and progression_status='eligible_for_upgrade';end$$;
create or replace function owner_resident_progress()returns table(id uuid,display_name text,username text,residency_year smallint,progression_status text,reassessment_due date,knowledge_completed bigint,skill_log_count bigint)language plpgsql stable security definer set search_path=public as $$begin if not is_owner()then raise exception'Owner only';end if;return query select p.id,p.display_name,p.username::text,p.residency_year,p.progression_status,p.reassessment_due,(select count(*)from knowledge_progress k where k.resident_id=p.id and status='completed'),(select count(*)from skill_logs l where l.resident_id=p.id)from profiles p where p.role='resident'order by p.residency_year,p.display_name;end$$;
alter table profiles enable row level security;alter table chapters enable row level security;alter table knowledge_items enable row level security;alter table skills enable row level security;alter table knowledge_progress enable row level security;alter table skill_levels enable row level security;alter table skill_logs enable row level security;alter table observer_reviews enable row level security;alter table assessor_assignments enable row level security;alter table assessment_deduction_reasons enable row level security;alter table assessments enable row level security;
create policy p_profiles_s on profiles for select to authenticated using(id=auth.uid()or is_owner()or(current_role()='assessor'and assessor_access(id,null)));create policy p_profiles_u on profiles for update to authenticated using(id=auth.uid()or is_owner());create policy p_curr_c on chapters for select to authenticated using(is_active or is_owner());create policy p_curr_k on knowledge_items for select to authenticated using(is_active or is_owner());create policy p_curr_s on skills for select to authenticated using(is_active or is_owner());create policy p_kp on knowledge_progress for all to authenticated using(resident_id=auth.uid()or is_owner()or assessor_access(resident_id,null))with check(resident_id=auth.uid());create policy p_slv on skill_levels for all to authenticated using(resident_id=auth.uid()or is_owner()or assessor_access(resident_id,null))with check(resident_id=auth.uid());create policy p_logs_s on skill_logs for select to authenticated using(resident_id=auth.uid()or is_owner()or assessor_access(resident_id,null));create policy p_logs_i on skill_logs for insert to authenticated with check(resident_id=auth.uid()and current_role()='resident');create policy p_rev_s on observer_reviews for select to authenticated using(observer_id=auth.uid()or is_owner()or assessor_access(resident_id,chapter_id));create policy p_rev_i on observer_reviews for insert to authenticated with check(observer_id=auth.uid()and current_role()='observer');create policy p_as on assessor_assignments for select to authenticated using(assessor_id=auth.uid()or is_owner());create policy p_aw on assessor_assignments for insert to authenticated with check(is_owner());create policy p_reason on assessment_deduction_reasons for select to authenticated using(is_active);create policy p_assess on assessments for select to authenticated using(resident_id=auth.uid()or assessor_id=auth.uid()or is_owner()or assessor_access(resident_id,chapter_id));
grant select,update on profiles to authenticated;grant select on chapters,knowledge_items,skills,assessment_deduction_reasons,assessments to authenticated;grant select,insert,update on knowledge_progress,skill_levels to authenticated;grant select,insert on skill_logs,observer_reviews,assessor_assignments to authenticated;grant usage,select on all sequences in schema public to authenticated;grant execute on all functions in schema public to authenticated;commit;
